// ── RULES MODAL ───────────────────────────────────────────────────────────────
function RulesModal({ mode, onClose }) {
  const isClassic = mode === "classic";
  const cards = RULE_CARDS[isClassic ? "classic" : "quickfire"] || [];
  // Match the Preview screen's card colour treatment: Classic = Caddie green,
  // Quick Fire = Gambler amber.
  const s = isClassic ? TYPE_STYLES.caddie : TYPE_STYLES.gambler;
  const headerTitle = isClassic ? "🏌️ Classic Rules" : "⚡ Quick Fire Rules";

  const [idx, setIdx] = useState(0);
  const touchX = React.useRef(null);
  const n = cards.length;
  const go = (d) => setIdx(i => Math.max(0, Math.min(n - 1, i + d)));

  const arrowStyle = (disabled) => ({
    width: 44, height: 44, borderRadius: "50%", cursor: disabled ? "default" : "pointer",
    background: disabled ? "#141414" : `${s.accent}22`,
    border: `1px solid ${disabled ? "#222" : s.border}`,
    color: disabled ? "#333" : s.accent, fontSize: 24, fontWeight: 900, lineHeight: 1,
    display: "flex", alignItems: "center", justifyContent: "center"
  });

  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(0,0,0,0.95)", zIndex: 300,
      display: "flex", flexDirection: "column", alignItems: "center",
      justifyContent: "center", padding: "18px 24px", gap: 14, overflowY: "auto"
    }}>
      <div style={{ color: s.accent, fontSize: 17, fontWeight: 900, letterSpacing: 1 }}>{headerTitle}</div>

      {/* Actual full-art rule card — presented exactly like a card preview */}
      <div
        onTouchStart={e => { touchX.current = e.touches[0].clientX; }}
        onTouchEnd={e => {
          if (touchX.current == null) return;
          const dx = e.changedTouches[0].clientX - touchX.current;
          if (dx < -40) go(1); else if (dx > 40) go(-1);
          touchX.current = null;
        }}
        style={{
          width: "min(300px, 78vw)", aspectRatio: "5 / 7", flexShrink: 0,
          borderRadius: 16, overflow: "hidden",
          border: `2px solid ${s.border}`, boxShadow: `0 0 40px ${s.border}55`,
          background: "#000"
        }}>
        <img src={cards[idx]} alt={`${headerTitle} card ${idx + 1}`}
          style={{ width: "100%", height: "100%", objectFit: "fill", display: "block" }} />
      </div>

      {n > 1 && (
        <>
          {/* Dot indicators */}
          <div style={{ display: "flex", gap: 6 }}>
            {cards.map((_, i) => (
              <button key={i} onClick={() => setIdx(i)} aria-label={`Card ${i + 1}`} style={{
                width: i === idx ? 22 : 8, height: 8, borderRadius: 4, border: "none",
                cursor: "pointer", padding: 0, background: i === idx ? s.accent : "#444",
                transition: "all 0.2s"
              }} />
            ))}
          </div>

          {/* Prev / counter / next */}
          <div style={{ display: "flex", alignItems: "center", gap: 18 }}>
            <button disabled={idx === 0} onClick={() => go(-1)} style={arrowStyle(idx === 0)}>‹</button>
            <div style={{ color: "#888", fontSize: 12, minWidth: 74, textAlign: "center" }}>Card {idx + 1} of {n}</div>
            <button disabled={idx === n - 1} onClick={() => go(1)} style={arrowStyle(idx === n - 1)}>›</button>
          </div>
        </>
      )}

      <button onClick={onClose} style={{
        background: s.accent, border: "none", borderRadius: 10,
        color: "#000", fontSize: 15, fontWeight: 900,
        padding: "12px 40px", cursor: "pointer"
      }}>Got it!</button>
    </div>
  );
}


