// ── SHOW YOUR HAND — redistribute this hole's scores ──────────────────────────
function ShowYourHandModal({ declarerId, scoresThisHole, players, onConfirm }) {
  // scoresThisHole: array of { playerId, score } sorted best (lowest) to worst (highest)
  const [assignments, setAssignments] = useState(scoresThisHole.map(s => ({ score: s.score, playerId: null })));
  const assignedPlayerIds = assignments.filter(a => a.playerId !== null).map(a => a.playerId);
  const currentIndex = assignments.findIndex(a => a.playerId === null);
  const isComplete = currentIndex === -1;

  function assign(playerId) {
    if (currentIndex === -1) return;
    setAssignments(a => a.map((row, i) => i === currentIndex ? { ...row, playerId } : row));
  }

  function unassign(index) {
    setAssignments(a => a.map((row, i) => i === index ? { ...row, playerId: null } : row));
  }

  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(0,0,0,0.95)", zIndex: 150,
      display: "flex", flexDirection: "column", alignItems: "center",
      justifyContent: "center", padding: "20px 24px", gap: 16, overflowY: "auto"
    }}>
      <div style={{ textAlign: "center", marginBottom: 4 }}>
        <div style={{ fontSize: 36, marginBottom: 6 }}>🏦</div>
        <div style={{ color: "#a855f7", fontSize: 11, fontWeight: 800, letterSpacing: 3 }}>THE HOUSE ALWAYS WINS</div>
        <div style={{ color: "#fff", fontSize: 18, fontWeight: 900, marginTop: 4 }}>Assign each score to a player</div>
        <div style={{ color: "#777", fontSize: 12, marginTop: 6, maxWidth: 320, lineHeight: 1.5 }}>
          Best to worst — pick who gets each score from this hole.
        </div>
      </div>

      {/* Score list with assigned players */}
      <div style={{ width: "100%", maxWidth: 360, display: "flex", flexDirection: "column", gap: 6 }}>
        {assignments.map((row, i) => {
          const assignedName = row.playerId ? players.find(p => p.id === row.playerId)?.name : null;
          const isCurrent = i === currentIndex;
          return (
            <div key={i} onClick={() => row.playerId && unassign(i)} style={{
              background: isCurrent ? "#1f0e30" : "#0f0f0f",
              border: `2px solid ${isCurrent ? "#a855f7" : "#2a2a2a"}`,
              borderRadius: 10, padding: "10px 14px",
              display: "flex", alignItems: "center", justifyContent: "space-between",
              cursor: row.playerId ? "pointer" : "default"
            }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ color: "#facc15", fontSize: 20, fontWeight: 900 }}>{row.score}</span>
                <span style={{ color: "#555", fontSize: 11 }}>{i === 0 ? "(best)" : i === assignments.length - 1 ? "(worst)" : ""}</span>
              </div>
              {assignedName ? (
                <span style={{ color: "#a855f7", fontSize: 13, fontWeight: 800 }}>{assignedName} ✕</span>
              ) : (
                <span style={{ color: "#444", fontSize: 12 }}>Unassigned</span>
              )}
            </div>
          );
        })}
      </div>

      {/* Player picker for the current score */}
      {!isComplete && (
        <div style={{ width: "100%", maxWidth: 360 }}>
          <div style={{ color: "#777", fontSize: 12, textAlign: "center", marginBottom: 8 }}>
            Who gets the score of {assignments[currentIndex].score}?
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {players.filter(p => !assignedPlayerIds.includes(p.id)).map(p => (
              <button key={p.id} onClick={() => assign(p.id)} style={{
                width: "100%", padding: "12px", background: "#1f0e30",
                border: "1px solid #a855f7", borderRadius: 10,
                color: "#fff", fontSize: 15, fontWeight: 700, cursor: "pointer"
              }}>{p.name}{p.id === declarerId ? " (you)" : ""}</button>
            ))}
          </div>
        </div>
      )}

      {isComplete && (
        <button onClick={() => onConfirm(assignments)} style={{
          width: "100%", maxWidth: 360, padding: "14px",
          background: "#a855f7", border: "none", borderRadius: 10,
          color: "#000", fontSize: 16, fontWeight: 900, cursor: "pointer"
        }}>Confirm Redistribution</button>
      )}
    </div>
  );
}

